func ptrRateMatrixDimension(p unsafe.Pointer, c int32) any {
	r := (*ratematrix.RateMatrixDimension)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RateMatrixID))
	case 4:
		return &r.VersionNumber
	case 5:
		return &r.Position
	case 6:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 7:
		return (*string)(unsafe.Pointer(&r.MatchMode))
	case 8:
		return &r.Label
	case 9:
		return (*string)(unsafe.Pointer(&r.KeyNormalization))
	case 10:
		return (*string)(unsafe.Pointer(&r.RangeOverflow))
	case 11:
		return &r.CreatedAt
	case 12:
		return &r.UpdatedAt
	}
	return nil
}

func valueRateMatrixDimension(p unsafe.Pointer, c int32) any {
	r := (*ratematrix.RateMatrixDimension)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RateMatrixID)
	case 4:
		return r.VersionNumber
	case 5:
		return r.Position
	case 6:
		return string(r.Kind)
	case 7:
		return string(r.MatchMode)
	case 8:
		if r.Label == "" {
			return nil
		}
		return r.Label
	case 9:
		return string(r.KeyNormalization)
	case 10:
		return string(r.RangeOverflow)
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	}
	return nil
}

func attachRateMatrixDimension(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*ratematrix.RateMatrixDimension)(p)
	switch rel {
	case 0:
		r.RateMatrix = (*ratematrix.RateMatrix)(child)
	}
}

